func newAuthLoginCmd(flags *rootFlags) *cobra.Command {
	var noBrowser bool

	cmd := &cobra.Command{
		Use:   "login",
		Short: "Authenticate via device authorization flow",
		Long: `Run a device authorization flow to obtain and save an Artyfacts API key.

The CLI prints a short URL and a one-time code. Open the URL in your browser,
enter the code, and the key is saved to your config automatically.`,
		Example:     "  artyfacts-pp-cli auth login\n  artyfacts-pp-cli auth login --no-browser",
		Annotations: map[string]string{"mcp:hidden": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			w := cmd.OutOrStdout()

			if cliutil.IsVerifyEnv() {
				fmt.Fprintln(w, "(verify env: skipping device auth flow)")
				return nil
			}

			flowResp, err := initiateDeviceFlow()
			if err != nil {
				return fmt.Errorf("starting device flow: %w", err)
			}

			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "To authorize this device, visit:")
			fmt.Fprintf(w, "  %s\n", flowResp.VerificationUri)
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "And enter this code:")
			fmt.Fprintf(w, "  %s\n", flowResp.UserCode)
			fmt.Fprintln(w, "")

			if !noBrowser {
				if openErr := openBrowser(flowResp.VerificationUri); openErr != nil {
					fmt.Fprintf(os.Stderr, "(could not open browser: %v)\n", openErr)
				}
			}

			fmt.Fprint(w, "Waiting for authorization")
			interval := flowResp.Interval
			if interval == 0 {
				interval = 5
			}

			authData, pollErr := pollDeviceToken(flowResp.DeviceCode, interval, w)
			fmt.Fprintln(w, "")
			if pollErr != nil {
				return fmt.Errorf("authorization failed: %w", pollErr)
			}

			cfg, cfgErr := config.Load(flags.configPath)
			if cfgErr != nil {
				return configErr(cfgErr)
			}
			cfg.AuthHeaderVal = ""
			if saveErr := cfg.SaveTokens("", "", authData.ApiKey, "", cfg.TokenExpiry); saveErr != nil {
				return configErr(fmt.Errorf("saving token: %w", saveErr))
			}

			if flags.asJSON {
				out := map[string]any{"authenticated": true, "config": cfg.Path}
				if authData.User != nil {
					out["email"] = authData.User.Email
				}
				return printJSONFiltered(w, out, flags)
			}

			fmt.Fprintln(w, "Authenticated!")
			if authData.User != nil {
				fmt.Fprintf(w, "  Signed in as: %s\n", authData.User.Email)
			}
			fmt.Fprintf(w, "  Token saved to %s\n", cfg.Path)
			return nil
		},
	}

	cmd.Flags().BoolVar(&noBrowser, "no-browser", false, "Print the URL but don't try to open a browser")
	return cmd
}

func initiateDeviceFlow() (*deviceFlowResponse, error) {
	resp, err := http.Post(artyfactsAPIBase+"/auth/device", "application/json", bytes.NewBufferString("{}"))
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
	}
	var out deviceFlowResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, err
	}
	return &out, nil
}

func pollDeviceToken(deviceCode string, intervalSecs int, w io.Writer) (*deviceTokenResponse, error) {
	body := map[string]string{
		"device_code": deviceCode,
		"client_id":   "artyfacts-claude",
	}
	for {
		time.Sleep(time.Duration(intervalSecs) * time.Second)

		bodyBytes, _ := json.Marshal(body)
		resp, err := http.Post(artyfactsAPIBase+"/auth/device/token", "application/json", bytes.NewReader(bodyBytes))
		if err != nil {
			return nil, err
		}
		var result deviceTokenResponse
		decodeErr := json.NewDecoder(resp.Body).Decode(&result)
		resp.Body.Close()
		if decodeErr != nil {
			return nil, decodeErr
		}

		if resp.StatusCode == http.StatusOK && result.ApiKey != "" {
			return &result, nil
		}

		switch result.Error {
		case "authorization_pending":
			fmt.Fprint(w, ".")
		case "slow_down":
			intervalSecs++
		case "access_denied":
			return nil, fmt.Errorf("authorization denied")
		case "expired_token":
			return nil, fmt.Errorf("device code expired — run login again")
		default:
			return nil, fmt.Errorf("%s", result.Error)
		}
	}
}

